style.css:
@-moz-document domain("mastodon.social"), domain("cmx.im") {
/* Version 3.0 */
/* Based on Purple Haze for Mastodon */
/* Sogo Osaka love */

:root {
/* --- 色板 --- */
  --haze-bg-deep:  #eaeaea; 
  --haze-bg-light: #f9f7fd; 
  --haze-bg-hover: #efebf5; 
  
  --haze-text-main: #30163E; /* 主要文字 */
  --haze-text-sub:  #705480; /* 次要文字 */
  
  --haze-brand:     #AE8CD1; 
  --haze-brand-dark:#9C77C2; 
  --haze-header:    #efe1ff; /* 灰色版本专门做个header颜色 */
  
  --haze-success:   #79bd9a; 
  --haze-error:     #9C77C2; 

/* --- 映射--- */

  /* 文字 */
  --color-text-primary: var(--haze-text-main);
  --color-text-secondary: var(--haze-text-sub);
  --color-text-tertiary: var(--haze-text-sub);
  --color-text-on-inverted: #ffffff;
  
  --color-text-error: var(--haze-error);
  --color-text-warning: var(--haze-brand-dark);
  --color-text-success: var(--haze-success);
  
  --color-text-brand: var(--haze-brand);
  --color-text-brand-soft: var(--haze-brand);
  --color-text-on-brand-base: #ffffff;
    
  --color-text-bookmark-highlight: var(--haze-error); 
  --color-text-favourite-highlight: var(--haze-brand-dark);

  /* 链接 */
  --color-link: var(--haze-brand);
  --color-link-hover: var(--haze-brand-dark);

  /* 背景 */
  --color-bg-primary: var(--haze-bg-light); 
  --color-bg-secondary: var(--haze-bg-light); 
  --color-bg-ambient: var(--haze-bg-deep);
  --color-bg-elevated: var(--haze-bg-light);
  --color-bg-inverted: var(--haze-text-main); 
  --color-bg-secondary-base: var(--haze-brand-dark);
  
  /* 遮罩与状态 */
  --color-bg-overlay: rgba(70, 55, 79, .6); 
  --color-bg-disabled: rgba(112, 84, 128, 0.1);
  --color-bg-brand-base: var(--haze-brand);
  --color-bg-brand-base-hover: var(--haze-brand-dark);
  --color-bg-brand-softer: var(--haze-bg-hover); 

  /* 边框 */
  --color-border-primary: rgba(112, 84, 128, 0.3);
  --color-border-secondary: rgba(112, 84, 128, 0.1);
  --color-border-on-bg-secondary: rgba(181, 136, 208, .31);
  --color-border-on-bg-brand-softer: rgba(181, 136, 208, .31);

  /* 按钮 */
  --button-background-color: var(--haze-brand);
  --button-text-color: #ffffff;
  --button-hover-background-color: var(--haze-brand-dark);
}

/* --- 布局更改 --- */

body {
  background: var(--haze-bg-deep) !important;
}

.column > .scrollable, 
.drawer__inner, 
.getting-started {
  background: var(--color-bg-primary) !important;
}

/* 顶部与导航栏 */
.drawer__header,
.column-header,
.column-back-button,
.notification__filter-bar {
    background: var(--haze-header); 
    color: var(--haze-text-sub);
}
.column-header__button {
    background: var(--haze-header);
    color: var(--haze-brand-deep);
}
.drawer__tab {
    color: var(--haze-brand-deep);
}

/* 下拉按钮修正 */
.dropdown-button.warning {
    color: var(--haze-text-main);
    border-color: var(--haze-text-main);
}
.dropdown-button.warning.active {
    color: #ffffff;
    border-color: var(--haze-brand); 
}

.column {
    background: var(--haze-bg-deep);
}
.column .link-footer {
    border-radius: 4px;
    background: var(--haze-bg-light);
} 

/* 导航栏对齐*/
.navigation-panel {
    background: var(--haze-bg-light);
    border-radius: 4px; 
}
/* 超大屏 */
@media screen and (min-width: 1175px) {
	.column:last-child, .drawer:last-child {
        margin-top: -10px !important;
    }	
}

/* Emoji 与输入框 */
.notification-group--favourite .notification-group__icon {
    color: var(--haze-brand);
}
.emoji-mart-bar:first-child {
    background: var(--color-bg-tertiary);
}
.emoji-mart-anchor {
    color: var(--haze-brand);
}
.emoji-mart-anchor-selected {
    color: var(--haze-text-sub); 
}
.emoji-mart-anchor-bar {
    background: var(--haze-text-sub); 
}
.compose-form__dropdowns {
    background: var(--haze-bg-light);
}
.compose-form .autosuggest-textarea__textarea, 
.compose-form .spoiler-input__input {
    background: #FFF;
    color: var(--haze-text-main);
}

/* 部分图标修正 */
.icon-button {
    --default-icon-color: var(--haze-brand);
    --hover-icon-color: var(--haze-text-main);
    --hover-bg-color: var(--haze-bg-hover);
    --default-bg-color: transparent;
}
.icon-button.active {
    --default-icon-color: var(--haze-text-sub);
    --hover-icon-color: var(--button-hover-background-color);
    --hover-bg-color: transparent;
}
.column-link__icon { color: var(--haze-brand) !important; }
.search__icon .fa { color: var(--haze-brand) !important; }
.column-link--logo {
    padding: 20px 10px 5px 10px;
}

/* --- 设置和管理 (Admin / Settings) --- */

body.admin, .admin-wrapper {
    background: var(--haze-bg-light) !important;
    color: var(--haze-text-main) !important;
}

.admin-wrapper .sidebar ul a {
    color: var(--haze-text-main); 
    background: transparent;
    border-radius: 4px; 
    transition: all 0.2s ease; 
}

.admin-wrapper .sidebar ul a:hover {
    background-color: var(--haze-bg-hover); 
    color: var(--haze-text-sub);
}

.admin-wrapper .sidebar ul .simple-navigation-active-leaf a {
    background-color: var(--haze-brand); 
    color: #ffffff !important;
    box-shadow: 0 2px 5px rgba(174, 140, 209, 0.4);
}

.admin-wrapper .sidebar ul .simple-navigation-active-leaf a:hover {
    background-color: var(--haze-brand-dark); 
    color: #ffffff !important;
}

.simple_form input[type=text], .simple_form input[type=number],
.simple_form input[type=email], .simple_form input[type=password],
.simple_form textarea, .simple_form select {
    background: #ffffff !important;
    color: var(--haze-text-main) !important;
    border: 1px solid var(--color-border-primary) !important;
    border-radius: 4px;
}
.simple_form input:focus, .simple_form textarea:focus, .simple_form select:focus {
    border-color: var(--haze-brand) !important;
    box-shadow: 0 0 0 2px var(--color-border-secondary);
}
.simple_form .hint { color: var(--haze-text-sub); }
.simple_form .label_input > label { color: var(--haze-text-main); }

.table > tbody > tr:nth-child(odd) > td, .table > tbody > tr:nth-child(odd) > th {
    background: var(--haze-bg-hover);
}
.table > tbody > tr:nth-child(even) > td, .table > tbody > tr:nth-child(even) > th {
    background: var(--haze-bg-light);
}
.table td, .table th {
    border-color: var(--color-border-primary);
    color: var(--haze-text-main);
}
.table a { 
    color: var(--haze-brand); 
}
.batch-table__toolbar, .batch-table__row {
    background: var(--haze-bg-light) !important;
    border-color: var(--color-border-primary) !important;
}
.account__header { 
    background: var(--haze-bg-light); 
}
.account__header .account__header__content { 
    color: var(--haze-text-main); 
}
.account__header .account__header__fields dt {
    color: var(--haze-text-main); 
}
.account__header .account__header__fields dd {
    color: var(--haze-text-sub); 
}

/* 多栏状态下拉菜单修正 */
.column-settings,
.column-header__advanced-buttons {
    background: var(--haze-bg-light) ;
}
.explore__search-header,
.account__section-headline {
	background: #F7EFFF ;
}



/* 非进阶式页面显示时的修正 */
.tabs-bar__wrapper {
    background: transparent;
}
.link-footer {
    background: var(--haze-bg-light);
    color: var(--haze-text-main) !important;
    border: 0;
    border-radius: 4px;
    padding: 10px;
}
.account .account__display-name .display-name strong,
.account--minimal .account__display-name .display-name { 
    color: var(--haze-text-sub);
}

/* 修正导航菜单 */
.column-link {
    transition: background-color 0.2s ease, color 0.2s ease;
}

.column-link:hover {
    color: var(--haze-brand-dark) !important;          
}

.column-link:hover .column-link__icon {
    color: var(--haze-brand-dark) !important;          
}
}
